"use client";

import Link from "next/link";
import { useMemo, useState, type CSSProperties } from "react";

export type VendorRow = { id: string; name: string; websiteUrl: string | null; status: string; sources: string[]; lastImport: string | null; placeholder: boolean };

const styles = { page: { minHeight: "100vh", minWidth: 1120, background: "#f9f8f6", padding: 32, color: "#292524" }, header: { display: "flex", justifyContent: "space-between", gap: 20, marginBottom: 24 }, breadcrumb: { display: "flex", gap: 8, marginBottom: 8, color: "#78716c", fontSize: 13 }, title: { margin: 0, fontSize: 20, fontWeight: 900 }, subtitle: { margin: "8px 0 0", color: "#78716c", fontSize: 13 }, primary: { minHeight: 36, display: "inline-flex", alignItems: "center", borderRadius: 5, background: "#a85e2a", color: "#fff", padding: "0 15px", textDecoration: "none", fontSize: 13, fontWeight: 900 }, card: { overflow: "hidden", border: "1px solid #e7e5e4", borderRadius: 8, background: "#fff" }, toolbar: { display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12, borderBottom: "1px solid #e7e5e4", padding: 16 }, controls: { display: "flex", gap: 10 }, input: { minHeight: 38, width: 320, border: "1px solid #d6d3d1", borderRadius: 5, padding: "0 12px" }, select: { minHeight: 38, border: "1px solid #d6d3d1", borderRadius: 5, background: "#fff", padding: "0 28px 0 10px" }, scroll: { overflowX: "auto" }, table: { width: "100%", minWidth: 900, borderCollapse: "collapse" }, th: { borderBottom: "1px solid #e7e5e4", background: "#fafaf9", padding: "14px 18px", color: "#78716c", textAlign: "left", fontSize: 11, fontWeight: 900, textTransform: "uppercase" }, td: { borderBottom: "1px solid #f5f5f4", padding: "16px 18px", fontSize: 13 }, name: { color: "#292524", fontWeight: 900 }, chip: { display: "inline-flex", border: "1px solid #e7e5e4", borderRadius: 5, background: "#f5f5f4", marginRight: 6, padding: "4px 8px", fontSize: 11 }, status: { textTransform: "capitalize" }, action: { color: "#a85e2a", fontWeight: 900, textDecoration: "none" }, muted: { color: "#a8a29e", fontSize: 12 }, footer: { minHeight: 56, display: "flex", justifyContent: "space-between", alignItems: "center", padding: "0 18px", color: "#78716c", fontSize: 12 }, button: { minHeight: 32, border: "1px solid #d6d3d1", borderRadius: 5, background: "#fff", padding: "0 12px" }, empty: { padding: 44, textAlign: "center", color: "#78716c" } } satisfies Record<string, CSSProperties>;

export function VendorsClient({ initialVendors }: { initialVendors: VendorRow[] }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [source, setSource] = useState(""); const [pageSize, setPageSize] = useState(20); const [page, setPage] = useState(1);
  const filtered = useMemo(() => initialVendors.filter((vendor) => (!query || `${vendor.name} ${vendor.websiteUrl ?? ""} ${vendor.sources.join(" ")}`.toLowerCase().includes(query.toLowerCase())) && (!status || vendor.status === status) && (!source || vendor.sources.includes(source))), [initialVendors, query, status, source]); const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize)); const currentPage = Math.min(page, pageCount); const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  return <div style={styles.page}><header style={styles.header}><div><nav aria-label="Breadcrumb" style={styles.breadcrumb}><Link href="/app" style={{ color: "inherit", textDecoration: "none" }}>Workspace</Link><span>›</span><strong aria-current="page">Vendors</strong></nav><h1 style={styles.title}>Vendors</h1><p style={styles.subtitle}>Manage supplier details and source ingestion methods.</p></div><Link href="/app/vendors/new" style={styles.primary}>New Vendor</Link></header><section style={styles.card}><div style={styles.toolbar}><div style={styles.controls}><input type="search" aria-label="Search vendors" placeholder="Search vendors, websites, or sources…" value={query} style={styles.input} onChange={(event) => { setQuery(event.target.value); setPage(1); }} /><select aria-label="Vendor status" value={status} style={styles.select} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All statuses</option><option value="active">Active</option><option value="onboarding">Onboarding</option><option value="inactive">Inactive</option></select><select aria-label="Source coverage" value={source} style={styles.select} onChange={(event) => { setSource(event.target.value); setPage(1); }}><option value="">All sources</option><option>Website</option><option>PDF</option></select></div><label style={styles.muted}>Vendors per page <select value={pageSize} style={styles.select} onChange={(event) => { setPageSize(Number(event.target.value)); setPage(1); }}><option>20</option><option>50</option><option>100</option></select></label></div>{visible.length ? <div style={styles.scroll}><table aria-label="Vendors" style={styles.table}><thead><tr><th style={styles.th}>Vendor Name</th><th style={styles.th}>Status</th><th style={styles.th}>Source Coverage</th><th style={styles.th}>Website</th><th style={styles.th}>Last Import</th><th style={{ ...styles.th, textAlign: "right" }}>Action</th></tr></thead><tbody>{visible.map((vendor) => <tr key={vendor.id}><td style={{ ...styles.td, ...styles.name }}>{vendor.name}{vendor.placeholder ? <div style={styles.muted}>Sample vendor</div> : null}</td><td style={{ ...styles.td, ...styles.status }}>{vendor.status}</td><td style={styles.td}>{vendor.sources.length ? vendor.sources.map((value) => <span key={value} style={styles.chip}>{value}</span>) : "Manual"}</td><td style={styles.td}>{vendor.websiteUrl ? new URL(vendor.websiteUrl).hostname : "Not provided"}</td><td style={styles.td}>{vendor.lastImport ? new Date(vendor.lastImport).toLocaleString() : "No imports"}</td><td style={{ ...styles.td, textAlign: "right" }}>{vendor.placeholder ? <span style={styles.muted}>Details unavailable</span> : <Link href={`/app/vendors/${vendor.id}`} style={styles.action}>View Details</Link>}</td></tr>)}</tbody></table></div> : <div style={styles.empty}>No vendors match the current search and filters.</div>}<footer style={styles.footer}><span>Showing {filtered.length ? (currentPage - 1) * pageSize + 1 : 0}–{Math.min(currentPage * pageSize, filtered.length)} of {filtered.length}</span><span><button style={styles.button} disabled={currentPage <= 1} onClick={() => setPage((value) => value - 1)}>Previous</button> Page {currentPage} of {pageCount} <button style={styles.button} disabled={currentPage >= pageCount} onClick={() => setPage((value) => value + 1)}>Next</button></span></footer></section></div>;
}
